import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const planeGeometry = new THREE.PlaneGeometry(1.6, 1.0);
  const surfaceMaterial = new MeshBasicNodeMaterial();
  surfaceMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const surface = new THREE.Mesh(planeGeometry, surfaceMaterial);
  surface.position.z = -0.02;
  root.add(surface);
  resources.push(planeGeometry, surfaceMaterial);

  const accentGeometry = new THREE.PlaneGeometry(1.28, 0.018);
  const accentMaterial = new MeshBasicNodeMaterial();
  accentMaterial.colorNode = vec3(1.0, 0.039, 0.094);

  const accent = new THREE.Mesh(accentGeometry, accentMaterial);
  accent.position.set(0, -0.39, 0.012);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;

    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center'
    });

    label.position.set(0, 0.015, 0.025);
    root.add(label);
  }

  surface.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) root.quaternion.copy(camera.quaternion);
  };

  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  texturePromise.then((tex) => {
    if (!tex || disposed) return;

    const atlas = config.atlasRegion ?? config.atlas ?? {};
    const source = atlas.sourceRect ?? atlas.rect ?? {
      x: 0,
      y: 0,
      width: 512,
      height: 320
    };
    const atlasWidth = atlas.width ?? source.width;
    const atlasHeight = atlas.height ?? source.height;

    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.offset.set(source.x / atlasWidth, 1 - (source.y + source.height) / atlasHeight);
    tex.repeat.set(source.width / atlasWidth, source.height / atlasHeight);
    if ('colorSpace' in tex && THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
    tex.needsUpdate = true;

    const grainNode = texture(tex);
    const engineeredGradient = mix(
      vec3(0.043, 0.043, 0.063),
      vec3(0.086, 0.086, 0.114),
      smoothstep(0.0, 1.0, uv().y)
    );

    surfaceMaterial.colorNode = mix(
      engineeredGradient,
      engineeredGradient.mul(grainNode),
      0.1
    );
    surfaceMaterial.needsUpdate = true;
    resources.push(tex);
  }).catch(() => {});

  const intro = gsap.timeline({ paused: true });
  intro.fromTo(
    surface.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' }
  );
  intro.play();
  timelines.push(intro);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline.kill();

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    root.traverse((object) => {
      if (object.userData) object.userData.handlers = {};
    });
  };

  return root;
}

export default createNode;
